import{_ as r,r as t,o as s,c as i,e as l,a as e,s as p,d as n}from"./chunks/framework.CXcwiNg-.js";const C=JSON.parse('{"title":"Коллекции - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Создание коллекций","slug":"создание-коллекции","link":"#создание-коллекции","children":[]},{"level":2,"title":"Доступные методы","slug":"доступные-методы","link":"#доступные-методы","children":[]}],"relativePath":"1.x/ru/services/collections.md","filePath":"1.x/ru/services/collections.md"}'),d={name:"1.x/ru/services/collections.md"};function h(u,o,m,_,f,v){const c=t("pre-heading"),a=t("post-heading");return s(),i("div",null,[l(c),o[0]||(o[0]=e("h1",null,"Коллекции",-1)),l(a),o[1]||(o[1]=p(`<p><a name="introduction" class="anchor"></a></p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>Класс <code>October\\Rain\\Support\\Collection</code> - гибкая и удобная обёртка для работы с массивами.</p><p>Для примера, взгляните на код ниже. Мы создадим новую коллекцию из массива и применим функцию <code>strtoupper</code> к каждому элементу. После чего удалим все пустые элементы:</p><pre><code>$collection = new October\\Rain\\Support\\Collection([&#39;stewie&#39;, &#39;brian&#39;, null]);

$collection = $collection
    -&gt;map(function ($name) {
        return strtoupper($name);
    })
    -&gt;reject(function ($name) {
        return empty($name);
    })
;
</code></pre><p>Как вы можете видеть, класс <code>Collection</code> позволяет строить цепочки вызовов для операций типа map и reduce над заданным массивом данных. В основном каждый метод класса <code>Collection</code> возвращает новый объект класса <code>Collection</code>.</p><p><a name="creating-collections" class="anchor"></a></p><h2 id="создание-коллекции"><a href="#создание-коллекции" class="header-anchor">#</a> Создание коллекций</h2><p>Просто передайте массив в конструктор класса <code>October\\Rain\\Support\\Collection</code>. Пример:</p><pre><code>$collection = new October\\Rain\\Support\\Collection([1, 2, 3]);
</code></pre><p>Там, где методы <a href="./../database/model.html">модели бд</a> возвращают не один, а несколько объектов - возвращается коллекция. Однако, коллекции предоставляют слишком мощный функционал. Попробуйте применить класс <code>Collection</code> у себя в приложении.</p><p><a name="available-methods" class="anchor"></a></p><h2 id="доступные-методы"><a href="#доступные-методы" class="header-anchor">#</a> Доступные методы</h2>`,13)),o[2]||(o[2]=e("p",null,[n("Вместо того, чтобы приводить здесь огромный скучный список методов коллекции, мы отсылаем вас к более удобной "),e("a",{href:"https://octobercms.com/docs/api/october/rain/support/collection",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("документации API этого класса"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),e("span",{class:"sr-only"},"(opens new window)")])]),n(".")],-1))])}const x=r(d,[["render",h]]);export{C as __pageData,x as default};
